exact_approved_CSS:
* { box-sizing: border-box; }
html { color-scheme: light; }
body { margin: 0; background: #fff; color: #202020; font: 17px/1.65 Arial, sans-serif; }
main { max-width: 820px; margin: 0 auto; padding: 34px 22px 64px; }
h1 { font-size: 2rem; line-height: 1.22; margin: 24px 0 14px; font-weight: 600; }
h2 { font-size: 1.35rem; line-height: 1.35; margin: 35px 0 12px; }
p { margin: 0 0 18px; }
a { color: #164a99; text-underline-offset: 2px; overflow-wrap: anywhere; }
.byline { color: #4c4c4c; font-size: .95rem; }
.formula { overflow-x: auto; padding: 5px 0 12px; white-space: nowrap; line-height: 1.9; }
.result { font-size: 1.15rem; }
iframe { display: block; width: 100%; height: 70vh; min-height: 450px; border: 1px solid #ddd; margin-top: 16px; }
footer { border-top: 1px solid #ddd; margin-top: 35px; padding-top: 18px; font-size: .93rem; color: #444; }
@media (max-width: 480px) { body { font-size: 16px; } main { padding: 22px 18px 44px; } h1 { font-size: 1.75rem; } iframe { min-height: 350px; } }
